V C_RuleTests::m_test_ranked_reach_is_an_ellipse_for_every_card(const Args& A) {
    V L_bloom;
    V L_card;
    V L_cx;
    V L_cy;
    V L_hero;
    V L_tile;
    V L_width;
    { V tv1_0 = V(48.0); V tv1_1 = V(10000.0); L_tile = std::move(tv1_0); L_width = std::move(tv1_1); }
    L_card = rd(pm_catalog::CARDS, SV("plant:豌豆射手"));
    L_hero = V::tuple({V(1000.0), V(500.0)});
    { V tv2_0 = rd(L_hero, V(0.0)); V tv2_1 = (rd(L_hero, V(1.0)) - L_tile); L_cx = std::move(tv2_0); L_cy = std::move(tv2_1); }
    (void)(m_assertEqual(Args{SV(""), pm_pvp61_ranked::f_ring_error(Args{L_card, L_hero, (L_cx + (V(11.9) * L_tile)), L_cy, L_tile, L_width})}));
    (void)(m_assertTrue(Args{pm_pvp61_ranked::f_ring_error(Args{L_card, L_hero, (L_cx + (V(12.1) * L_tile)), L_cy, L_tile, L_width})}));
    (void)(m_assertEqual(Args{SV(""), pm_pvp61_ranked::f_ring_error(Args{L_card, L_hero, L_cx, (L_cy + (V(7.9) * L_tile)), L_tile, L_width})}));
    (void)(m_assertTrue(Args{pm_pvp61_ranked::f_ring_error(Args{L_card, L_hero, L_cx, (L_cy + (V(8.1) * L_tile)), L_tile, L_width})}));
    L_bloom = rd(pm_catalog::CARDS, SV("plant:黄金蓓蕾"));
    (void)(m_assertTrue(Args{pm_pvp61_ranked::f_ring_error(Args{L_bloom, L_hero, (L_cx + (V(5.9) * L_tile)), L_cy, L_tile, L_width})}));
    (void)(m_assertEqual(Args{SV(""), pm_pvp61_ranked::f_ring_error(Args{L_bloom, L_hero, (L_cx + (V(6.1) * L_tile)), L_cy, L_tile, L_width})}));
    (void)(m_assertEqual(Args{V(1.5), pm_pvp61_ranked::ELLIPSE_X}));
    return V::none();
}

V C_RuleTests::m_test_quiet_producers_ramp_to_fifty_percent(const Args& A) {
    V L_plant;
    L_plant = py_dict({{SV("植物血"), V(6.0)}});
    (void)(m_assertEqual(Args{V(1.0), pm_balance::f_rest_factor(Args{L_plant, V(0.0), pm_catalog::RULES})}));
    (void)(m_assertEqual(Args{V(1.0), pm_balance::f_rest_factor(Args{L_plant, (V(12.0) * V(250.0)), pm_catalog::RULES})}));
    (void)(m_assertAlmostEqual(Args{V(1.25), pm_balance::f_rest_factor(Args{L_plant, (V(30.0) * V(250.0)), pm_catalog::RULES})}));
    (void)(m_assertAlmostEqual(Args{V(1.5), pm_balance::f_rest_factor(Args{L_plant, (V(48.0) * V(250.0)), pm_catalog::RULES})}));
    (void)(m_assertAlmostEqual(Args{V(1.5), pm_balance::f_rest_factor(Args{L_plant, (V(99.0) * V(250.0)), pm_catalog::RULES})}));
    setm(L_plant, &Obj::植物血, SV("植物血"), V(7.0));
    (void)(m_assertAlmostEqual(Args{V(1.5), pm_balance::f_rest_factor(Args{L_plant, (V(100.0) * V(250.0)), pm_catalog::RULES})}));
    setm(L_plant, &Obj::植物血, SV("植物血"), V(5.0));
    (void)(m_assertEqual(Args{V(1.0), pm_balance::f_rest_factor(Args{L_plant, (V(101.0) * V(250.0)), pm_catalog::RULES})}));
    (void)(m_assertEqual(Args{V(1.0), pm_balance::f_rest_factor(Args{L_plant, (V(113.0) * V(250.0)), pm_catalog::RULES})}));
    (void)(m_assertAlmostEqual(Args{V(1.25), pm_balance::f_rest_factor(Args{L_plant, (V(131.0) * V(250.0)), pm_catalog::RULES})}));
    return V::none();
}

V C_RuleTests::m_test_sky_interval_follows_map_size(const Args& A) {
    (void)(m_assertEqual(Args{V(8.0), pm_balance::f_sky_interval(Args{pm_catalog::RULES, V(72.0), V(24.0)})}));
    (void)(m_assertEqual(Args{V(4.0), pm_balance::f_sky_interval(Args{pm_catalog::RULES, V(144.0), V(48.0)})}));
    (void)(m_assertAlmostEqual(Args{V(6.0), pm_balance::f_sky_interval(Args{pm_catalog::RULES, V(96.0), V(32.0)})}));
    (void)(m_assertEqual(Args{V(8.0), pm_balance::f_sky_interval(Args{pm_catalog::RULES, V(48.0), V(16.0)})}));
    (void)(m_assertEqual(Args{V(4.0), pm_balance::f_sky_interval(Args{pm_catalog::RULES, V(200.0), V(100.0)})}));
    return V::none();
}

